GRANT SELECT,INSERT,UPDATE,DELETE,REFERENCES,TRIGGER,TRUNCATE ON public.apsol_facturacion TO anon,authenticated,service_role;

-- backups datados (revertibles con INSERT ... SELECT desde zz_bkp_*)
