-- ===== FACTURACION: espejo =====
-- NOTA: prospecto_id / contacto_cobro_id / contacto_cobro2_id NO se tocan en el UPDATE.
-- El sheet solo tiene los ids hex viejos; la DB ya resolvio esas FKs en la import original
-- (0 huerfanos). Solo se escriben los campos que el sheet manda de verdad.
DELETE FROM apsol_private.pagos WHERE facturacion_id NOT IN (SELECT (sid||'-0000-0000-0000-000000000000')::uuid FROM stg_fact);
DELETE FROM apsol_private.facturacion WHERE id NOT IN (SELECT (sid||'-0000-0000-0000-000000000000')::uuid FROM stg_fact);
UPDATE apsol_private.facturacion f SET
  fecha_emision=s.fecha, monto=s.monto, periodo_desde=s.pdesde, periodo_hasta=s.phasta,
  proxima_notificacion=s.prox, ultima_notificacion=s.ult, solo_invoice=s.soloinv,
  archivo_factura=s.fac1, numero_factura=s.nrofac, documento_general=s.doc,
  notas=s.obs, leyenda=s.leyenda, porcentaje_descuento=COALESCE(s.descuento,0), hs_facturadas=s.hs
FROM stg_fact s WHERE f.id=(s.sid||'-0000-0000-0000-000000000000')::uuid;
-- INSERT de facturas del sheet que no existan en la DB (FKs con guarda EXISTS -> si no resuelve, NULL)
INSERT INTO apsol_private.facturacion
 (id,fecha_emision,monto,periodo_desde,periodo_hasta,contacto_cobro_id,contacto_cobro2_id,prospecto_id,
  proxima_notificacion,ultima_notificacion,solo_invoice,archivo_factura,numero_factura,documento_general,
  notas,leyenda,porcentaje_descuento,hs_facturadas)
SELECT (s.sid||'-0000-0000-0000-000000000000')::uuid,s.fecha,s.monto,s.pdesde,s.phasta,
  (SELECT c.id FROM apsol_private.contactos c WHERE c.id=s.c1),
  (SELECT c.id FROM apsol_private.contactos c WHERE c.id=s.c2),
  (SELECT p.id FROM apsol_private.prospectos p WHERE p.id=s.prospecto),
  s.prox,s.ult,s.soloinv,s.fac1,s.nrofac,s.doc,s.obs,s.leyenda,COALESCE(s.descuento,0),s.hs
FROM stg_fact s
WHERE NOT EXISTS (SELECT 1 FROM apsol_private.facturacion f WHERE f.id=(s.sid||'-0000-0000-0000-000000000000')::uuid);

-- ===== PAGOS: recarga total desde la hoja (espejo exacto) =====
DELETE FROM apsol_private.pagos;
INSERT INTO apsol_private.pagos(id,facturacion_id,fecha,monto,observaciones)
SELECT gen_random_uuid(),s.fac,s.fecha,s.monto,s.obs FROM stg_pago s
WHERE EXISTS (SELECT 1 FROM apsol_private.facturacion f WHERE f.id=s.fac);

