-- ===== FACTURAS COLABORADORES: espejo =====
DELETE FROM apsol_private.facturas_colaboradores;
INSERT INTO apsol_private.facturas_colaboradores(id,colaborador_id,fecha_factura,numero_factura,monto,archivo_factura,fecha_pago,comprobante_pago)
SELECT fid,colab,fecha,nro,monto,arch,fpago,comp FROM stg_fcol;

-- ===== CONTRATOS: espejo =====
DELETE FROM apsol_private.contratos;
INSERT INTO apsol_private.contratos(id,colaborador_id,tipo_contrato,fecha_inicio,fecha_fin,dias_libres_por_mes,tipo_honorarios,honorarios,adjunto,adjunto2,estado)
SELECT cid,colab,tipo,fini,ffin,dias,tipohon,hon,adj,adj2,estado::apsol_private.estado_general FROM stg_contr;

-- ===== recalcular estado =====
UPDATE apsol_private.facturacion f SET estado = CASE
  WHEN COALESCE(p.pagado,0) >= f.monto THEN 'Cobrada total'
  WHEN COALESCE(p.pagado,0) > 0 THEN 'Cobrada parcial'
  ELSE 'Pendiente' END::apsol_private.estado_factura
FROM (SELECT facturacion_id,SUM(monto) pagado FROM apsol_private.pagos GROUP BY 1) p WHERE p.facturacion_id=f.id;
UPDATE apsol_private.facturacion SET estado='Pendiente' WHERE id NOT IN (SELECT facturacion_id FROM apsol_private.pagos);

-- ===== VERIFICACION (RAISE -> ROLLBACK) =====
DO $$
DECLARE nf int; np int; sp numeric; nfc int; nc int; np_sheet int;
BEGIN
  SELECT count(*) INTO nf FROM apsol_private.facturacion;
  IF nf<>364 THEN RAISE EXCEPTION 'facturacion=% esperado 364 -> ROLLBACK', nf; END IF;
  SELECT count(*), round(coalesce(sum(monto),0),2) INTO np, sp FROM apsol_private.pagos;
  SELECT count(*) INTO np_sheet FROM stg_pago;
  SELECT count(*) INTO nfc FROM apsol_private.facturas_colaboradores;
  IF nfc<>56 THEN RAISE EXCEPTION 'facturas_colab=% esperado 56 -> ROLLBACK', nfc; END IF;
  SELECT count(*) INTO nc FROM apsol_private.contratos;
  IF nc<>21 THEN RAISE EXCEPTION 'contratos=% esperado 21 -> ROLLBACK', nc; END IF;
  RAISE NOTICE 'RESULTADO: facturacion=% (esp 364) | pagos=% de % en la hoja (suma %) | facturas_colab=% (esp 56) | contratos=% (esp 21)', nf, np, np_sheet, sp, nfc, nc;
  IF np <> np_sheet THEN
    RAISE NOTICE 'ATENCION: % pagos de la hoja no entraron (factura destino inexistente). Revisar.', np_sheet - np;
  END IF;
END $$;

COMMIT;